// Package: Microsoft.Extensions.Configuration.AzureAppConfiguration
// Install: dotnet add package Microsoft.Extensions.Configuration.AzureAppConfiguration

using Azure.Identity;
using Microsoft.Extensions.Configuration.AzureAppConfiguration;

var builder = WebApplication.CreateBuilder(args);

// Add Azure App Configuration with Key Vault references resolved automatically
var appConfigUri = new Uri(builder.Configuration["Azure:AppConfig:Uri"]!);

builder.Configuration.AddAzureAppConfiguration(options =>
{
    options.Connect(appConfigUri, new DefaultAzureCredential())
           .Select(KeyFilter.Any, LabelFilter.Null)
           .UseFeatureFlags(ff =>
           {
               ff.CacheExpirationInterval = TimeSpan.FromSeconds(30);
           });
});

// Enable dynamic configuration refresh in controllers
builder.Services.AddAzureAppConfiguration();

var app = builder.Build();
app.UseAzureAppConfiguration();

app.MapGet("/config/{key}", (string key, IConfiguration config) =>
{
    var value = config[key];
    Console.WriteLine($"Key: {key}, Value: {value}");
    return Results.Ok(new { key, value });
});
app.Run();

// Expected output:
// Key: AppSettings:WelcomeMessage, Value: Hello from Azure App Configuration

// Package: Microsoft.FeatureManagement.AspNetCore
// Install: dotnet add package Microsoft.FeatureManagement.AspNetCore

using Microsoft.FeatureManagement;

// Register feature management with Azure App Configuration
builder.Services.AddFeatureManagement();

app.MapGet("/new-ui", async (IFeatureManagerService features, CancellationToken ct) =>
{
    try
    {
        bool isEnabled = await features.IsEnabledAsync("NewUi", ct);
        if (isEnabled)
        {
            Console.WriteLine("Feature 'NewUi' is enabled");
            return Results.Ok("Welcome to the new UI");
        }

        Console.WriteLine("Feature 'NewUi' is disabled");
        return Results.NotFound("Feature not available");
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Feature check failed: {ex.Message}");
        return Results.Problem("Feature evaluation error");
    }
});

// Expected output (feature enabled):
// Feature 'NewUi' is enabled
